#!/usr/bin/env python3
# Generates app/css/themes.css: the twelve "whole feel" app styles for Iqra 1.2.
# SVG art is written here and inlined as data URIs so the styles need no extra files.
import random
from urllib.parse import quote

import os
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'app', 'css', 'themes.css')

def svg(body, w, h, extra=''):
    s = f"<svg xmlns='http://www.w3.org/2000/svg' width='{w}' height='{h}' viewBox='0 0 {w} {h}' {extra}>{body}</svg>"
    return 'url("data:image/svg+xml,' + quote(s, safe=" '=:/,.-()") + '")'

def noise(color='0 0 0', alpha=0.08, freq=0.85, size=240, octaves=3, seed=3):
    r, g, b = color.split()
    return svg(f"<filter id='n'><feTurbulence type='fractalNoise' baseFrequency='{freq}' numOctaves='{octaves}' seed='{seed}' stitchTiles='stitch'/>"
               f"<feColorMatrix values='0 0 0 0 {r} 0 0 0 0 {g} 0 0 0 0 {b} 0 0 0 {alpha * 9} -{alpha * 3.4}'/></filter>"
               f"<rect width='100%' height='100%' filter='url(#n)'/>", size, size)

random.seed(7)
css = []
add = css.append

