# ---------------------------------------------------------------- per-style art
import re
def style(sid, block):
    # generated covers use each book's own hue (--h), which only exists on the cover element, so the
    # cover variables are moved from :root onto .gen-cover where var(--h) can resolve
    extra = []
    def pull(m):
        sel, body = m.group(1), m.group(2)
        g = re.search(r'--gen-bg: ([^;]*);\s*(--gen-fg: [^;]*;)?', body)
        if g:
            body = body.replace(g.group(0), '')
            target = ':root[S] .gen-cover' if 'dark' not in sel else ':root[S][data-mode="dark"] .gen-cover'
            extra.append(f'{target} {{ --gen-bg: {g.group(1)}; {g.group(2) or ""} }}')
        return sel + '{' + body + '}'
    block = re.sub(r'(:root\[S\](?:\[data-mode="dark"\])? )\{(.*?)\}\n', lambda m: pull(m) + '\n', block, flags=re.S)
    block += '\n'.join(extra) + '\n'
    add(f'\n/* ======================== {sid} ======================== */')
    add(block.replace('[S]', f'[data-style="{sid}"]'))

