# ===== 4. BOGOLAN (mud cloth) =====
def bogolan_tile(c):
    c = c.replace('#', '%23')
    b = (f"<g fill='{c}' stroke='{c}'>"
         f"<rect x='0' y='0' width='120' height='120' fill='none' stroke-width='3'/>"
         + ''.join(f"<circle cx='{8 + i * 13}' cy='8' r='2.6' stroke='none'/>" for i in range(9))
         + "<path d='M4 30 l10 -10 l10 10 l10 -10 l10 10 l10 -10 l10 10 l10 -10 l10 10 l10 -10 l10 10 l10 -10 l10 10' fill='none' stroke-width='3'/>"
         + "<rect x='12' y='44' width='34' height='34' fill='none' stroke-width='3'/><rect x='21' y='53' width='16' height='16' fill='none' stroke-width='3'/><circle cx='29' cy='61' r='3' stroke='none'/>"
         + "<path d='M72 46 v30 M57 61 h30' stroke-width='4'/><circle cx='62' cy='51' r='2.5' stroke='none'/><circle cx='82' cy='51' r='2.5' stroke='none'/><circle cx='62' cy='71' r='2.5' stroke='none'/><circle cx='82' cy='71' r='2.5' stroke='none'/>"
         + "<path d='M100 44 v34 M108 44 v34' stroke-width='3'/>"
         + ''.join(f"<path d='M{6 + i * 16} 92 l6 10 l6 -10' fill='none' stroke-width='3'/>" for i in range(7))
         + ''.join(f"<rect x='{6 + i * 16}' y='108' width='8' height='6' stroke='none'/>" for i in range(7)) + "</g>")
    return svg(b.replace('%23', '#'), 120, 120)
