# ===== 5. INDIGO (tie-dye / batik) =====
def tiedye(c1, n=9, w=360, h=360, seed=4):
    rnd = random.Random(seed)
    b = ''
    for _ in range(n):
        x, y, r = rnd.uniform(0, w), rnd.uniform(0, h), rnd.uniform(28, 64)
        for k in range(4):
            rr = r - k * 9
            if rr > 4:
                b += f"<circle cx='{x:.0f}' cy='{y:.0f}' r='{rr:.0f}' fill='none' stroke='{c1}' stroke-width='{3.2 - k * .5:.1f}' stroke-dasharray='{rnd.randint(3, 9)} {rnd.randint(2, 6)}' opacity='{.55 - k * .1:.2f}'/>"
        b += f"<circle cx='{x:.0f}' cy='{y:.0f}' r='3' fill='{c1}' opacity='.6'/>"
    return svg("<filter id='f'><feGaussianBlur stdDeviation='.9'/></filter><g filter='url(#f)'>" + b + "</g>", w, h)
def crackle(c, w=400, h=260, seed=9):
    rnd = random.Random(seed)
    b = ''
    for _ in range(26):
        x, y = rnd.uniform(0, w), rnd.uniform(0, h)
        d = f'M{x:.0f} {y:.0f}'
        for _ in range(rnd.randint(3, 7)):
            x += rnd.uniform(-40, 40); y += rnd.uniform(-30, 30); d += f' L{x:.0f} {y:.0f}'
        b += f"<path d='{d}' fill='none' stroke='{c}' stroke-width='{rnd.uniform(.6, 1.6):.1f}' opacity='.5'/>"
    return svg(b, w, h)
ind_mark = svg("<circle cx='20' cy='20' r='17' fill='#1f3b8f'/>" + ''.join(f"<circle cx='20' cy='20' r='{r}' fill='none' stroke='#f4f6fa' stroke-width='1.6' stroke-dasharray='3 2'/>" for r in (13, 8, 3.5)), 40, 40)
