# ===== 7. ZELLIGE: 8-point star tiles =====
def zellige_tile(line, fills):
    import math
    s = 80
    def star(cx, cy, r1, r2):
        pts = []
        for k in range(16):
            a = k * math.pi / 8 - math.pi / 16
            r = r1 if k % 2 == 0 else r2
            pts.append(f'{cx + math.cos(a) * r:.1f},{cy + math.sin(a) * r:.1f}')
        return ' '.join(pts)
    b = f"<rect width='{s}' height='{s}' fill='{fills[0]}'/>"
    for (cx, cy) in [(0, 0), (s, 0), (0, s), (s, s)]:
        b += f"<polygon points='{star(cx, cy, 30, 22)}' fill='{fills[1]}' stroke='{line}' stroke-width='2'/>"
        b += f"<polygon points='{star(cx, cy, 13, 8)}' fill='{fills[2]}' stroke='{line}' stroke-width='1.5'/>"
    b += f"<polygon points='{star(s / 2, s / 2, 24, 17)}' fill='{fills[3]}' stroke='{line}' stroke-width='2'/>"
    b += f"<circle cx='{s / 2}' cy='{s / 2}' r='5' fill='{fills[2]}' stroke='{line}' stroke-width='1.5'/>"
    return svg(b, s, s)
zt_day = zellige_tile('#f4f1ea', ['#e8e3d8', '#0f6e64', '#d9a52a', '#1f4fa0'])
zt_soft = zellige_tile('rgba(255,255,255,.0)', ['transparent', 'rgba(15,110,100,.07)', 'rgba(217,165,42,.08)', 'rgba(31,79,160,.06)'])
zt_night = zellige_tile('#0a2026', ['#0f2e37', '#127a6e', '#e9b949', '#2b5fb8'])
zel_mark = svg("<polygon points='20,2 25,13 37,10 30,20 37,30 25,27 20,38 15,27 3,30 10,20 3,10 15,13' fill='#0f6e64' stroke='#d9a52a' stroke-width='1.5'/><circle cx='20' cy='20' r='5' fill='#d9a52a'/>", 40, 40)
