# ===== 10. RAINY WINDOW =====
def droplets(w=300, h=300, n=60, seed=5):
    rnd = random.Random(seed)
    b = ''
    for _ in range(n):
        x, y, r = rnd.uniform(0, w), rnd.uniform(0, h), rnd.uniform(1.2, 4.2)
        b += f"<ellipse cx='{x:.0f}' cy='{y:.0f}' rx='{r:.1f}' ry='{r * 1.15:.1f}' fill='rgba(255,255,255,.28)' stroke='rgba(40,70,90,.18)' stroke-width='.7'/><circle cx='{x - r / 3:.1f}' cy='{y - r / 3:.1f}' r='{r / 3.2:.1f}' fill='rgba(255,255,255,.75)'/>"
    return svg(b, w, h)
